import{_ as n,l,o as e,c as o,v as t,p as s,x as i,d as g,i as d,S as u}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Bewley–Huggett–Aiyagari","description":"","frontmatter":{"title":"Bewley–Huggett–Aiyagari","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/bewley-aiyagari.md","filePath":"econ/bewley-aiyagari.md","lastUpdated":1789023840000}'),p={name:"econ/bewley-aiyagari.md"};function m(c,a,h,A,_,y){const r=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="bewley–huggett–aiyagari" tabindex="-1">Bewley–Huggett–Aiyagari <a class="header-anchor" href="#bewley–huggett–aiyagari" aria-label="Permalink to &quot;Bewley–Huggett–Aiyagari&quot;">​</a></h1><div class="epigraph"><p>劳动收入不可完全保险时，家庭用无风险资产自保；均衡利率使资产需求等于外生供给（或资本）。</p><footer>—— Bewley；Huggett, The Risk-Free Rate in Heterogeneous-Agent Incomplete-Insurance Economies, JEDC 1993；Aiyagari, Uninsured Idiosyncratic Risk and Aggregate Saving, QJE 1994</footer></div><p><a href="/econ/narrative-hf-identification">上一课</a>把加总冲击识别到能画 IRF 为止。IRF 背后仍是代表性欧拉。本课缺口是<strong>关掉完全保险</strong>：特异收入风险 + 借贷约束 ⇒ 财富分布成为均衡对象。不重做 SVAR，不把 Krusell–Smith 的总量冲击提前写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>代表性 Ramsey 的 \\(\\beta(1+r)=1\\) 钉死稳态利率。Huggett：只有债券、净供给为零或外生，异质禀赋与约束下，预防性需求把 \\(r\\) 压到时间偏好之下。Aiyagari：资产是生产性资本，特异风险提高总储蓄，稳态 \\(K\\) 高于完全保险经济。Bewley 传统提供装置。缺口不是再讲预防性储蓄的 \\(u&#39;&#39;&#39;\\)，而是：不完全市场一般均衡把分布 \\(\\mu(a,z)\\) 与价格一起解。</p><p><span class="marginnote">Huggett, <em>JEDC</em> 1993。Aiyagari, <em>QJE</em> 109(3), 1994, 659–684。Imrohoroglu 同期有失业自保。本课是稳态，总量确定。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>个人状态 \\((a,z)\\)，\\(z\\) 为收入马尔可夫。政策 \\(a&#39;=g(a,z;r)\\) 由贝尔曼（本课程第一课的算子）加 \\(a&#39;\\ge\\underline a\\)。不变分布 \\(\\mu\\) 满足 \\(\\mu=T_g\\mu\\)。出清：\\(\\int a&#39;\\,d\\mu=A\\)（债券）或 \\(=\\int k\\,d\\mu\\)（资本）。算法：猜 \\(r\\)，解家庭，更新总量，直到出清。这是 VFI 加分布迭代，不是新理论。</p>',8)),(e(),s(u,null,{default:i(()=>[d(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E7%8C%9C%20r%22%5D%20--%3E%20HH%5B%22%E8%A7%A3%E5%AE%B6%E5%BA%AD%20g%22%5D%0A%20%20HH%20--%3E%20MU%5B%22%E4%B8%8D%E5%8F%98%E5%88%86%E5%B8%83%20%CE%BC%22%5D%0A%20%20MU%20--%3E%20MKT%5B%22%E8%B5%84%E4%BA%A7%E5%87%BA%E6%B8%85%22%5D%0A%20%20MKT%20--%3E%20R%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[g(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>加总消费仍较平滑：特异风险在截面抵消。总量矩可以看起来像代表性模型，微观 MPC 与财富基尼不行——后课逐条拆。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是自保需求抬高资产价格（压低 \\(r\\)）或抬高 \\(K\\)。约束附近的人欧拉变不等式，MPC 高；富人接近完全市场欧拉，MPC 低。加总欧拉不是某个 \\(u&#39;(C)\\)，而是财富加权的一阶条件混合。代表性 DSGE 的贝叶斯估计吃不到这个混合，除非显式异质。</p><p>没有总量冲击时，宏观时间序列是平的。周期要靠外生总量 \\(Z_t\\)——下一课 Krusell–Smith：分布成为总量状态。</p><p><span class="marginnote">稳态财富分布往往比数据更薄的右尾，因为收入过程不够持久、没有收益异质或创业。帕累托尾是再后课。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课无总量风险、无名义刚性、无政府。HANK 把 NK 价格粘性接进来，不是本课。也不估计收入过程的全部计量（Guvenen、Kaplan 等后用）。劳动供给内生、离散选择、耐久品，都是同一装置的扩充。</p><p>后课默认：不完全市场稳态 = 家庭贝尔曼 + 不变分布 + 资产出清；\\(r\\lt \\rho\\) 可来自预防性。下一课：加上总量冲击，分布如何被「近似」成有限状态。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Huggett/Aiyagari：不可保风险 + 约束 ⇒ 分布与 \\(r\\)（或 \\(K\\)）联立。</li><li>加总可平滑，微观 MPC 已异质。</li><li>稳态、无总量冲击。</li><li>出处：Huggett, <em>JEDC</em> 1993；Aiyagari, <em>QJE</em> 1994。</li></ul>',10))])}const B=n(p,[["render",m]]);export{f as __pageData,B as default};
